\begin{definition}[Rounds of quantum queries]\label{def:rounds}
Let $H \colon \mathcal{X} \to \mathcal{Y}$. A quantum oracle algorithm $\mathsf{A}^{(\cdot)}$ \emph{asks at most $q$ queries in at most $d$ rounds} if, on every input, its execution relative to $H$ can be written as
\[
  U_{d}\, O_H^{\otimes k_{d}}\, U_{d-1} \cdots U_{1}\, O_H^{\otimes k_{1}}\, U_{0}
\]
applied to a fixed initial state, followed by a measurement of a designated output register, where the unitaries $U_0, \dots, U_{d}$ do not depend on $H$ and the widths satisfy $k_1, \dots, k_{d} \ge 0$ and $\sum_{i=1}^{d} k_i \le q$. Randomized algorithms are included by letting $U_0$ prepare a uniform superposition over a randomness register that is measured at the start. A \emph{classical-query} algorithm is the special case in which every query register is measured in the computational basis immediately before each application of $O_H^{\otimes k_i}$.
\end{definition}

\begin{definition}[Fully quantum time-lock puzzle in the quantum random oracle model]\label{def:qgqs-tlp}
Let $n = n(\kappa)$, $m = m(\kappa)$ and $\rho = \rho(\kappa)$. A \emph{fully quantum time-lock puzzle with generator query complexity $n$, solver query complexity $m$ and completeness error $\rho$} is a pair $\Pi = (\mathsf{Gen}, \mathsf{Sol})$ of quantum oracle algorithms such that:
\begin{itemize}
  \item $\mathsf{Gen}^{H}(r_G)$, on randomness $r_G$, makes at most $n$ quantum queries to $H$ and outputs a pair of classical strings $(\mathsf{P}, \mathsf{s})$, the puzzle and its solution;
  \item $\mathsf{Sol}^{H}(\mathsf{P})$ makes at most $m$ quantum queries to $H$ and outputs a classical string $\mathsf{s}'$;
  \item (completeness) $\Pr\!\left[\mathsf{s} = \mathsf{s}' \;:\; (\mathsf{P}, \mathsf{s}) \leftarrow \mathsf{Gen}^{H}(r_G),\; \mathsf{s}' \leftarrow \mathsf{Sol}^{H}(\mathsf{P})\right] \ge 1 - \rho$, over the uniform choice of $H$, the choice of $r_G$, and the measurements of $\mathsf{Gen}$ and $\mathsf{Sol}$.
\end{itemize}
No restriction is placed on the number of rounds in which $\mathsf{Gen}$ and $\mathsf{Sol}$ ask their queries; in particular the honest solver may need all $m$ of its queries to be sequential, which is what a time-lock puzzle intends to exploit.
\end{definition}
